export const library = {"version":"1.1.0","question_version":"1.0.0","schema_version":"1.0.0","products":{"past":{"name":"你的上一世是什么？","equal_title":"你的前世档案，不止一页","intro":"旧日档案馆查到了这些和你相近的故事。","bases":[{"id":"P1","code":"---","name":"山寺门口的一段石阶","job":"山门休息区固定资产","daily_scene":"香客来来往往，你专挑下午有太阳的那一截待着。偶尔掉下一颗栗子，你也不汇报。","signature":"一片刚好落在旁边的银杏叶","quote":"“路可以慢慢走，先坐一会儿。”","gentle_reminder":"看起来什么也没做，其实把休息的位置留了很久。","variants":{"low":{"id":"P1-low","name":"山门午休石阶","scene":"香客歇脚时最先找到你。业务很简单：稳稳待着，不催任何人。"},"mid":{"id":"P1-mid","name":"夹着落叶的石阶","scene":"你记得哪一级方便歇脚，也收下每年落在旁边的几片叶子。"},"high":{"id":"P1-high","name":"月光最后照到的石阶","scene":"白天留给赶路的人，夜里收下一点月光，安静也有自己的颜色。"}},"core_text":"前世片段：你躺在山寺门前，见过赶早的人、歇脚的人和忘带伞的人。大家从你身上经过，你只管把那一小段路留得稳稳当当。\n\n今生线索：你更容易在熟悉、安静、可以细看的生活里恢复自己。擅长把一段普通日子过得有秩序，也可能因为太习惯而错过想尝试的事。小提醒：给固定路线留一个小岔口，不必一下换掉整个人生。\n\n晒图句：**“前世已经看过太多人，今生先允许自己安静一会儿。”**"},{"id":"P2","code":"--+","name":"老巷里的修伞匠","job":"雨天售后部老师傅","daily_scene":"午后刚想泡茶，门口又多了一把散架的伞。你嘴上说‘放那儿吧’，手已经开始找工具。","signature":"少了一颗扣子却一直没扔的围裙","quote":"“别急着买新的，我先看看。”","gentle_reminder":"怕一开口表达在乎，别人发现你其实特别认真。","variants":{"low":{"id":"P2-low","name":"一把伞也不放弃的修伞匠","scene":"你的浪漫藏在伞骨里：先把东西修好，再说别的。"},"mid":{"id":"P2-mid","name":"旧伞与旧故事修补员","scene":"问一句哪里坏了，也听一句它陪谁走过；但修补费不收故事税。"},"high":{"id":"P2-high","name":"把雨声缝进伞面的修伞匠","scene":"别人拿回一把修好的伞，你记住的是那天门口的雨声。"}},"core_text":"前世片段：你的铺子不大，窗边挂着旧伞。有人把散了架的东西递过来，你低头理好伞骨，再轻轻说一句“还能用”。\n\n今生线索：你喜欢自己的节奏，也愿意亲手把想法变成东西。你的表达常藏在细节里；有时会埋头做完，却忘了告诉别人自己付出了什么。小提醒：做好的东西可以拿出来，不用等到一点瑕疵都没有。\n\n晒图句：**“我表达在乎的方式：先把那把漏雨的伞修好。”**"},{"id":"P3","code":"-+-","name":"老街茶馆的掌柜","job":"熟人关系长期维护员","daily_scene":"你能从进门的脚步听出客人今天想聊天还是想安静，热水先倒上，话题不用着急。","signature":"一把总给晚到的人留着的椅子","quote":"“照旧？还是今天想换一杯？”","gentle_reminder":"店里每个人都有座位，你自己总是站着。","variants":{"low":{"id":"P3-low","name":"热水永远续得上的掌柜","scene":"谁坐哪儿不一定记成故事，茶有没有凉你先注意到了。"},"mid":{"id":"P3-mid","name":"记得茶钱也记得名字的掌柜","scene":"账本清楚，熟人的近况也装在心里，二者都不用大声宣告。"},"high":{"id":"P3-high","name":"替人留一张靠窗椅的掌柜","scene":"你会把某个下午记很久，哪怕当时只是在陪人坐着。"}},"core_text":"前世片段：你记得谁爱坐窗边，谁点茶其实只是想找人说句话。客人来来去去，店里总有一把没急着收走的椅子。\n\n今生线索：你喜欢熟悉的人和持续的关系，也会留意别人今天有哪里不同。这个本领容易让人放松；它也可能让你过度留在“照顾气氛”的位置。小提醒：偶尔让别人替你续一次茶。\n\n晒图句：**“你不用想好怎么开口，先坐下。”**"},{"id":"P4","code":"-++","name":"小城赶集的手艺人","job":"把日子做漂亮的小摊主","daily_scene":"上午把摊支好，下午已经多了几件临时改出来的小物。熟客说‘还是你懂我要啥’，你假装很淡定。","signature":"一个装着边角料的旧铁盒","quote":"“这个可以改，给我一会儿。”","gentle_reminder":"别人一句‘你做得好’，容易让你又多接一件。","variants":{"low":{"id":"P4-low","name":"把日子做顺手的手艺人","scene":"东西先做得好用，再添点漂亮；摊位座右铭是‘用着舒服才算数’。"},"mid":{"id":"P4-mid","name":"烟火与巧思一起摆摊的人","scene":"一个小东西既能解决麻烦，也能让人带回一点好心情。"},"high":{"id":"P4-high","name":"会把花纹做成故事的手艺人","scene":"你的边角料也有名字，普通物件容易被你添上一段来历。"}},"core_text":"前世片段：每到赶集日，你带着亲手做的小物出门。客人说起想要的样子，你边听边改，摊位上总有一点新鲜东西。\n\n今生线索：你喜欢在稳定生活里，和熟人一起做出看得见的成果。一起下厨、布置、筹备活动，往往比空谈更让你满足。代价是容易不知不觉接下所有准备工作。小提醒：把“我来做”换成一次“我们分着做”。\n\n晒图句：**“日子不用惊天动地，能亲手做漂亮就很好。”**"},{"id":"P5","code":"+--","name":"跟着季风迁徙的候鸟","job":"无固定工位的看景员","daily_scene":"你停在屋檐上看下面的人赶路。别人以为你没有安排，你只是把‘想多看一会儿’也写进安排。","signature":"一张没有写归期的车票","quote":"“我先去看看，到了再说。”","gentle_reminder":"怕一答应停留，大家就以为你永远不会走。","variants":{"low":{"id":"P5-low","name":"沿途食宿侦察鸟","scene":"你喜欢换地方，也记得哪里方便落脚，沿途风景和实际条件一起看。"},"mid":{"id":"P5-mid","name":"带着沿途片段的候鸟","scene":"路线要走得通，沿途遇见的光也想多记一会儿。"},"high":{"id":"P5-high","name":"把季风当来信的候鸟","scene":"风吹到哪里，你就替那段路记一小句诗，没写完也无妨。"}},"core_text":"前世片段：你的旧日地址总在变。你在不同河岸停留，看过人烟，也看过空旷；有些地方只待了一晚，却记了很久。\n\n今生线索：你对新地方有兴趣，同时珍惜独自观察的自由。容易注意到别人匆匆经过的细节；有时为了保留退路，也不愿承诺停留。小提醒：自由可以包括主动选一个地方，好好待上一阵。\n\n晒图句：**“我会停下来，只是想自己决定停在哪里。”**"},{"id":"P6","code":"+-+","name":"四处游历的画师","job":"沿途小事收集兼创作员","daily_scene":"客栈的窗漏进一点光，你本想只歇脚，结果又画到茶凉。收拾行李时，发现纸比衣服还多。","signature":"一支短得快拿不住的笔","quote":"“等等，这个我想记下来。”","gentle_reminder":"脑子里的新作品开了八个头，手上还只做完一个。","variants":{"low":{"id":"P6-low","name":"走到哪画到哪的实景画师","scene":"桥长什么样、街口怎么转，你更愿意把看到的具体东西画清楚。"},"mid":{"id":"P6-mid","name":"把日常画成画的旅人","scene":"一半记下真实地方，一半留下当时心情；茶凉了也算画面的一部分。"},"high":{"id":"P6-high","name":"画里总藏一段心事的游历者","scene":"同一座桥到了你笔下，会多一点情绪和故事。"}},"core_text":"前世片段：一卷纸、一支笔，你把住过的客栈、见过的桥和没来得及说的话都装进行囊。走了一段路，就添一幅画。\n\n今生线索：你想遇见新东西，也喜欢把感受变成自己的表达。独处能帮助你形成想法；新点子太多时，也容易每一件都只做一半。小提醒：选一件正在做的，让它有个小小的结尾。\n\n晒图句：**“我经过的地方，会留下一点属于我的痕迹。”**"},{"id":"P7","code":"++-","name":"渡口的摆渡人","job":"人间短途故事接收员","daily_scene":"有人上船说了一路，有人一句话不说。你都送到岸边，不要求每个故事都有结局。","signature":"一盏只照亮这一小程的灯","quote":"“先坐稳，到岸了我叫你。”","gentle_reminder":"听别人说目的地久了，会忘记自己也有想去的地方。","variants":{"low":{"id":"P7-low","name":"记得船稳不稳的摆渡人","scene":"你留意这一程是否坐得舒服、什么时候能到岸，照应常落在具体事情上。"},"mid":{"id":"P7-mid","name":"听一路也送一路的摆渡人","scene":"到岸是正事，沿途的闲话也值得听，不需要争哪个更重要。"},"high":{"id":"P7-high","name":"送人过河也记住晚霞的人","scene":"别人到岸离开，夕阳下的一句话还会在你心里停一会儿。"}},"core_text":"前世片段：你每天遇见不同的人，听一段赶路的故事，再送他们到另一岸。你未必认识所有名字，却知道有人需要缓一缓再出发。\n\n今生线索：你喜欢变化中的相遇，乐于听人讲，也不急着把每次相遇变成作品。好奇心让你的世界很宽；有时会听进太多别人的事，留下太少自己的时间。小提醒：今天也问一句“我想去哪一岸”。\n\n晒图句：**“世界很大，先把这一程走好。”**"},{"id":"P8","code":"+++","name":"走南闯北的说书人","job":"无聊下午紧急救援员","daily_scene":"你本来只想买碗面，坐下十分钟，旁边两桌已经开始听故事。面快坨了，你还在说‘最后一句’。","signature":"一把说到兴头就展开的折扇","quote":"“我跟你说，这事后来更离谱。”","gentle_reminder":"安静一下会担心场子冷了，忍不住再补一个笑话。","variants":{"low":{"id":"P8-low","name":"把真事讲清楚的说书人","scene":"事情怎么发生、哪里转了弯，你愿意讲明白，现场不靠空泛的玄乎。"},"mid":{"id":"P8-mid","name":"三分见闻七分热闹的说书人","scene":"这句比例只是包袱：故事有真切细节，也留着笑与回味。"},"high":{"id":"P8-high","name":"能把一碗面讲成传奇的人","scene":"一件小事经你留意，会长出意象和余味，面凉是职业风险。"}},"core_text":"前世片段：你一到镇上，茶桌就多围了几个人。昨天在路上撞见的小插曲，今天已经变成让大家笑出声的新故事。\n\n今生线索：变化、相遇和表达都能给你能量。你能把经历讲活，带动共同活动；有时为了有趣，日程安排得太满，自己却累了。小提醒：不是每个晚上都需要有故事，留一个晚上什么也不发生。\n\n晒图句：**“我一来，平平无奇的下午就多了一段故事。”**"}],"suffixes":{"low":"烟火档案**：“你的旧日档案里，最清楚的是饭菜的热气、伞是否漏雨、桌子是否稳。你常靠具体的东西认识世界。给今生留的物件：一只用着顺手的搪瓷杯。”","mid":"半卷烟火，半卷诗**：“你既记得事情怎样发生，也记得它让人有何感受。你的前世行囊里，一半是日常，一半是舍不得丢的碎片。给今生留的物件：夹着旧票根的小本子。”","high":"有诗的档案**：“一阵风、一盏灯、一个没说完的句子，都容易在你心里继续生长。故事感给日常添颜色；若解释太多，也可以先回到眼前的事实。给今生留的物件：写了一半的信。”"}},"next":{"name":"你的下一世是什么？","equal_title":"转世窗口给你留了不止一个位置","intro":"按你想要的生活，转世窗口列出了这些安排。","bases":[{"id":"N1","code":"---","name":"旧院里晒太阳的石头","job":"终身免考勤的晒太阳专员","daily_scene":"九点晒左边，三点晒右边。路过的人说你今天没什么变化，你觉得今天这束光已经很不错。","signature":"上午的太阳＋下午的太阳","quote":"“我在，但今天不提供产出。”","gentle_reminder":"允许自己停下来以后，别把所有新鲜事也一起关掉。","variants":{"low":{"id":"N1-low","name":"墙根静音晒太阳石","scene":"院子很静，你只需判断今天哪一束光更暖，全年没有日报。"},"mid":{"id":"N1-mid","name":"能听见生活声的院落石","scene":"隔壁切菜声、门口脚步声偶尔经过，你晒太阳时顺便听两耳朵。"},"high":{"id":"N1-high","name":"院门彩灯下的快乐石","scene":"白天晒太阳，晚上看院门彩灯。你不动，热闹可以从旁边经过。"}},"core_text":"下一世片段：你卧在老院的墙根，上午晒一面，下午晒另一面。有人从旁边经过，你不必起身，也不必交代今天完成了什么。\n\n愿望线索：你选的是固定归处、独享空间和可以直接享受的生活。这个愿望允许“存在”本身就够；提醒是，休息也可以有变化，不必把所有新东西挡在门外。今生小试验：留半小时，做一件不用产出的事。\n\n转世备注：**“本次申请免除：必须时刻有用。”**"},{"id":"N2","code":"--+","name":"山间慢慢开花的树","job":"不按季度汇报的生长员","daily_scene":"别的树先开了花，你还在长叶子。山风没有催你，春天也没给你发‘进度如何’的消息。","signature":"私人季节＋自定花期","quote":"“我有自己的花期。”","gentle_reminder":"别天天看着枝头检查进度，叶子也值得庆祝。","variants":{"low":{"id":"N2-low","name":"山谷静静开花树","scene":"风声很轻，枝叶慢慢长，没有观众也愿意按自己的花期生活。"},"mid":{"id":"N2-mid","name":"有风有鸟的慢生树","scene":"安静与生活声轮流来访，花开得慢，日子不必单调。"},"high":{"id":"N2-high","name":"四季都想换颜色的树","scene":"叶色、花朵、阳光都能变成体验；长在原地也可以过彩色生活。"}},"core_text":"下一世片段：你在山坡扎根，春天添一片叶，合适的时候开花。没有谁要求你每天汇报生长进度，枝头却一年比一年更像你自己。\n\n愿望线索：你想有安稳、独立的空间，也想慢慢养成属于自己的成果。这适合长期投入；有时也会盯着成长，忘了享受已经长出的叶子。今生小试验：给一个小项目留自己的节奏，只和上次的自己比较。\n\n转世备注：**“允许晚开花，允许按自己的季节生长。”**"},{"id":"N3","code":"-+-","name":"有人偏爱的家猫","job":"富婆家带薪午睡体验员","daily_scene":"她刚铺好床，你就上去验收。她加班回来，你先蹭一下，再把最暖的位置继续占着。","signature":"固定饭票＋专属窗台＋可拒绝抱抱","quote":"“本世忙完，下世再躺。”","gentle_reminder":"享受偏爱，也保留想自己待着的那个角落。","variants":{"low":{"id":"N3-low","name":"富婆家的静音午睡猫","scene":"一个固定窗台，一个愿意轻声说话的人，亲近时也不用开满音量。"},"mid":{"id":"N3-mid","name":"自己选音量的被偏爱猫","scene":"想贴贴就过去，想休息就回窝，家里给你的空间一直在。"},"high":{"id":"N3-high","name":"住在彩色大房子的团宠猫","scene":"窗外有动静，屋里有玩具，想凑热闹时走两步就有人回应。"}},"core_text":"下一世片段：你有固定窗台、热乎的小窝和熟悉的人。那个人拿起手机给你拍照时，你只管把肚皮藏好，再伸个懒腰。\n\n愿望线索：你想要可靠陪伴，也想安心享受被照顾的日常。你可能喜欢“富婆家的猫”这个玩笑，真正对应的是不必时时表现的安心关系。提醒是，被照顾与拥有自己的空间可以同时成立。今生小试验：向可信的人提出一个具体、可拒绝的小请求。\n\n转世备注：**“俗称富婆家的猫，核心福利是偏爱与安心。”**"},{"id":"N4","code":"-++","name":"只开半天店的早餐老板","job":"允许准时关门的小店主","daily_scene":"上午把粥煮香，中午门口牌子翻成‘明天见’。有人问下午怎么不开，你回答‘下午我要过日子’。","signature":"生活保障＋半天营业＋整段下午","quote":"“上午卖早餐，下午归我。”","gentle_reminder":"喜欢的事也要有收工时间，不必越做越满。","variants":{"low":{"id":"N4-low","name":"安静小巷半日店主","scene":"少量熟客、轻声招呼，中午准时关门，下午交还自己。"},"mid":{"id":"N4-mid","name":"把热粥与闲话一起端来的店主","scene":"有人聊天，也有人安静吃完；店里给两种日子都留位置。"},"high":{"id":"N4-high","name":"街口热闹半日早餐老板","scene":"早晨笑声和锅气一起起，收摊照样准时，营业热闹不代表必须加班。"}},"core_text":"下一世片段：你的店开在喜欢的小城，收入不依赖营业时长。熟人早晨来喝一碗热粥，中午卷帘门一拉，你去过自己的下午。\n\n愿望线索：你想扎根、有人往来，也想亲手做出东西。满足感来自持续的生活联系和自己的作品；容易把喜欢的事又排成满满的任务。今生小试验：做一顿自选菜单的饭，提前定好结束时间。\n\n转世备注：**“做喜欢的事，也保留关门的权利。”**"},{"id":"N5","code":"+--","name":"不用下雨的云","job":"天空编制之外的自由漫游员","daily_scene":"飘过写字楼时有人抬头看你。你停了几分钟，没带来天气预报要求的任何业务指标。","signature":"不限方向＋允许发呆＋不必降雨","quote":"“今天也不用证明自己有用。”","gentle_reminder":"拥有方向选择权，也可以主动选一次停留。","variants":{"low":{"id":"N5-low","name":"远山上不用下雨的云","scene":"把天空的音量调小，慢慢飘过山顶，今天没有业务需求。"},"mid":{"id":"N5-mid","name":"路过人间屋顶的闲云","scene":"时而停在空旷处，时而看看人间日常，你有自己的音量旋钮。"},"high":{"id":"N5-high","name":"晚霞里会换颜色的云","scene":"想看热闹就飘过亮灯的街区，想安静就离开，不必固定一种颜色。"}},"core_text":"下一世片段：你飘过河流、屋顶和放学的小路。今天想停在山上就停，明天想去海边就走，天空没有考勤机。\n\n愿望线索：你选的是移动自由、独享空间和不必持续产出的体验。你想给日子多一点余地；若一直保留所有可能，也容易很难做决定。今生小试验：给自己一次没有打卡目标的散步，同时选好回来的时间。\n\n转世备注：**“批准：偶尔停留，随时拥有自己的方向。”**"},{"id":"N6","code":"+-+","name":"把种子带远的风","job":"到处留下小作品的流动创作者","daily_scene":"吹过窗台，带走一点花香；转过山坡，送下几粒种子。你的作品分散各地，没有统一打卡墙。","signature":"自由路线＋沿途创作＋随时换景","quote":"“我来过，留下了一点东西。”","gentle_reminder":"给一个项目留到收尾，不必每次换景都重新开始。","variants":{"low":{"id":"N6-low","name":"轻声播种的山间风","scene":"轻轻绕过山坡，把一点种子放下，作品生长不用锣鼓助阵。"},"mid":{"id":"N6-mid","name":"窗边与田野之间的风","scene":"有时经过安静的草地，有时带走小店花香，自由里有自己的小成果。"},"high":{"id":"N6-high","name":"把花香吹过夜市的风","scene":"丰富气味和灯光都经过你，顺路给生活添一点新的颜色。"}},"core_text":"下一世片段：你从田野吹到山坡，带走一点花香，顺手把种子送到新的地方。没有固定办公室，留下的东西却在各处慢慢生长。\n\n愿望线索：你希望自由移动，也想留下自己的创作或改变。兴趣广、起步快是可贵的资源；可能每到一处都想重新开始。今生小试验：带着同一个小项目换个环境继续做，让自由和完成一起发生。\n\n转世备注：**“一路有风，一路留下自己的东西。”**"},{"id":"N7","code":"++-","name":"和伙伴结伴远游的海豚","job":"无需抢票的结伴出游会员","daily_scene":"同伴一招呼，你们就往海湾游。想停的时候停，谁想单独玩一会儿，也不用在群里解释半天。","signature":"自由出发＋伙伴同行＋各自空间","quote":"“下次出发，希望你也在。”","gentle_reminder":"一起出发不必每一步都同步，分开一会儿也能会合。","variants":{"low":{"id":"N7-low","name":"安静海湾结伴海豚","scene":"喜欢的人在旁边，不一定要一直说话，海湾给你们留了安静。"},"mid":{"id":"N7-mid","name":"各自自在又能同行的海豚","scene":"一起看新地方，也各自玩一会儿，什么时候会合可以慢慢商量。"},"high":{"id":"N7-high","name":"一路看新鲜的结伴海豚","scene":"海湾、浪花和新景色接连出现，热闹旅程里也留着喜欢的伙伴。"}},"core_text":"下一世片段：你和喜欢的伙伴一路游，碰见漂亮海湾就多待一会儿。没有抢票、调休和订酒店，见面也不用翻三个人的日历。\n\n愿望线索：你想自由，也想有人分享沿途的快乐，体验本身已经足够。共同出行会给你满足；别忘了同伴的节奏未必总一致。今生小试验：约一位熟人去近处走走，各自留一段自由安排。\n\n转世备注：**“下次出发，希望喜欢的人也在。”**"},{"id":"N8","code":"+++","name":"走到哪儿演到哪儿的街头乐手","job":"全球自由开演兼自由停演员","daily_scene":"把乐器往街角一放，有人停下听，有人加入唱。今天没灵感？你把座位让出来，自己当观众。","signature":"基础收入＋自由舞台＋不演也可以","quote":"“想唱就唱，想听就听。”","gentle_reminder":"不必每次相遇都负责精彩，做观众也是参与。","variants":{"low":{"id":"N8-low","name":"轻声开演的旅行乐手","scene":"小小一场歌，几位愿意听的人；观众少也不妨碍表达自己的东西。"},"mid":{"id":"N8-mid","name":"演与听都自由的街角乐手","scene":"今天热闹合唱，明天安静独奏，想做观众时就把位置让出来。"},"high":{"id":"N8-high","name":"走到哪儿亮到哪儿的乐手","scene":"新舞台、新伙伴、新声音都让你心动，谢幕以后也可以真正下班。"}},"core_text":"下一世片段：你带着乐器去不同地方，唱给愿意停一会儿的人。收入有保障，演不演由你决定；今天没灵感，也可以听别人唱。\n\n愿望线索：你想流动、相遇、表达，并在共同体验中留下作品。这个愿望很有生命力；容易把每次相遇都变成需要表现的场合。今生小试验：和熟人做一个小作品，也允许其中有人只来听。\n\n转世备注：**“世界很大，找几个地方唱自己的歌。”**"}],"suffixes":{"low":"静音转世**：“你的理想生活需要足够少的干扰。转世窗口替你保留了安静角落，热闹可以参加，也可以随时离开。感官预算：简单舒服。”","mid":"自选音量**：“你既喜欢平静，也愿意偶尔被新鲜东西点亮。转世窗口附送音量旋钮，今天热闹，明天清静，都由你选。”","high":"彩色转世**：“你希望生活有更多颜色、声音和体验。转世窗口把街灯、集市与新鲜气味装进行囊；记得留一个能把音量关小的角落。”"}},"cat":{"name":"你是哪一种流浪猫？","equal_title":"你的猫咪档案有不止一张脸","intro":"城市地图上，找到了这些和你相近的猫咪身份。","bases":[{"id":"C1","code":"---","name":"屋顶独行猫","job":"天台晒太阳产权持有猫","daily_scene":"楼下的人喊了三声咪咪，你看了一眼，把尾巴挪开两厘米。已经是今天相当正式的回应。","signature":"认路不难，交心较慢","quote":"“可以认识我，请慢一点。”","gentle_reminder":"想让人知道你需要支持时，光挪尾巴可能不够。","variants":{"low":{"id":"C1-low","name":"软爪屋顶隐士","scene":"有人靠近得太快，你先挪远一点，再找合适时候说明；距离也是一句话。"},"mid":{"id":"C1-mid","name":"看场合营业的屋顶猫","scene":"有时只看一眼，有时认真说明，是否开放屋顶由你自己决定。"},"high":{"id":"C1-high","name":"屋顶边界公告猫","scene":"你清楚表示‘先别靠这么近’，关系可以慢慢来，地盘说明先到位。"}},"core_text":"猫咪片段：你有固定的一块屋顶，知道哪片瓦下午最暖。有人路过，你看一眼；伸手想摸，你可以挪到自己喜欢的距离。\n\n人间线索：你珍惜熟悉地盘，信任需要时间，也更常自己处理需要。你能维持独立空间；有时别人很难知道你其实需要一点支持。小提醒：向可信的人透露一个具体需要，不必一下交出全部心事。\n\n猫咪营业范围：远处观察，熟人靠近。\n\n晒图句：**“可以认识我，请慢一点。”**"},{"id":"C2","code":"--+","name":"保安亭编外猫","job":"门卫室合作单位，不接受绩效考核","daily_scene":"门卫打开小门，你顺势进来，蹲在脚边。允许一起值一会儿班，暂不接受未经预约的摸头。","signature":"固定搭档，可以合作，不必立刻交心","quote":"“合作可以，乱摸不行。”","gentle_reminder":"关系可以偶尔从‘有事找你’变成‘没事也问问你’。","variants":{"low":{"id":"C2-low","name":"轻声提需求的保安亭猫","scene":"门可以请人帮开，摸头可晚些再谈，你愿意温和地说明两者不同。"},"mid":{"id":"C2-mid","name":"有合作也有分寸的编外猫","scene":"合适时就喵一声求助，不合适时就说明边界，值班不等于卖萌包月。"},"high":{"id":"C2-high","name":"编外岗位说明书猫","scene":"‘帮忙可以，抱起不行。’你的合作条款写得清楚，双方都省猜。"}},"core_text":"猫咪片段：你在小区固定巡逻，常蹲在保安亭旁。没打算和每个人交朋友，但需要开门时，你知道找谁喵一声。\n\n人间线索：你喜欢稳定，交心谨慎，同时懂得使用可靠支持。你不必先成为朋友才协作；代价是关系可能一直停留在“有事再说”。小提醒：有空时也可以问问那个帮过你的人，今天过得怎么样。\n\n猫咪营业范围：合作可以，乱摸不行。\n\n晒图句：**“交情慢慢来，事情可以一起办。”**"},{"id":"C3","code":"-+-","name":"单元门口等人猫","job":"熟悉脚步声鉴别员","daily_scene":"门一响，你就抬头；人一坐下，你就靠近。窝里的垫子歪了，你自己拖正，没叫任何人帮忙。","signature":"欢迎靠近，求助按钮偶尔失灵","quote":"“我想靠近，也会自己安排。”","gentle_reminder":"练习叫一声，让愿意靠近的人知道需要什么。","variants":{"low":{"id":"C3-low","name":"门口轻轻叫人的猫","scene":"你愿意靠近，也会缓缓说明不喜欢什么；轻声需求仍值得被听到。"},"mid":{"id":"C3-mid","name":"亲近有度的单元门猫","scene":"你可以蹭过去，也可以适时说明想独处，陪伴不必全天在线。"},"high":{"id":"C3-high","name":"亲近但边界清楚的等人猫","scene":"熟悉的人回来你会接近，需要自己的空间时也会直接讲清。"}},"core_text":"猫咪片段：你记得熟悉脚步声，听到门开会走过去蹭一下。旁边的小窝坏了，你却先自己把垫子拖好，没急着叫人。\n\n人间线索：你喜欢稳定相处，容易接受善意，也习惯把需要留给自己处理。亲近与独立在你身上同时存在；有时你对别人开放，却不愿开口麻烦他们。小提醒：已经愿意靠近的人，也可以知道你需要什么。\n\n猫咪营业范围：欢迎陪伴，求助另说。\n\n晒图句：**“我会等你，但也可以练习叫你一声。”**"},{"id":"C4","code":"-++","name":"菜市场营业猫","job":"整条街的小熟人","daily_scene":"你从菜摊走到杂货铺，每家都有人认识你。今天社交额度用完，就钻回自己的安全小窝睡觉。","signature":"熟人网络很强，午休必须保留","quote":"“今天熟人很多，下午也要打烊。”","gentle_reminder":"别人喜欢你，不等于你必须一直回应。","variants":{"low":{"id":"C4-low","name":"菜市场温柔打烊猫","scene":"熟人太多时，你先找个缓冲方式表达要休息，不必等电量耗尽。"},"mid":{"id":"C4-mid","name":"自选营业时间的市场猫","scene":"忙的时候回应，累的时候说明，今天的社交额度不必和昨天一样。"},"high":{"id":"C4-high","name":"准点挂休息牌的营业猫","scene":"你热情，也会清楚告诉大家今天到此为止；熟人不拥有全天权限。"}},"core_text":"猫咪片段：卖菜的大姨叫你，店里的熟客也认得你。你有固定地盘，渴了会去熟悉的水碗旁，累了就回自己的小窝。\n\n人间线索：熟悉的圈子让你放松，你愿意接近，也会主动表达需要。你很会形成日常互助；有时周围太多人找你，自己的休息容易被挤掉。小提醒：营业时间可以写上“今天提前打烊”。\n\n猫咪营业范围：熟人很多，仍然需要午休。\n\n晒图句：**“这条街有我认识的人，也有我的位置。”**"},{"id":"C5","code":"+--","name":"夜行侦察猫","job":"小区地图持续更新员","daily_scene":"夜色安静时，你又找到一条新路。白天有人问你去哪了，你只留下‘喵’这个过于简略的出差报告。","signature":"地图很大，交心名单很短","quote":"“我先去看看，熟悉了再带你。”","gentle_reminder":"留个轻松的联络方式，独立也可以被人知道。","variants":{"low":{"id":"C5-low","name":"轻步退场的夜行猫","scene":"遇到不舒服的接近，你更愿先缓一下，保持距离再说明需要。"},"mid":{"id":"C5-mid","name":"看路也看场合的侦察猫","scene":"新路线愿意走，关系慢慢看，表达方式按情境选。"},"high":{"id":"C5-high","name":"路线自由边界明确猫","scene":"你能直接说自己想怎么安排，不必用失联替代所有边界说明。"}},"core_text":"猫咪片段：天色暗一点，你就去走白天没走过的路。你知道围墙哪里能绕、哪扇窗会亮；地图越大，脚步反而越轻。\n\n人间线索：你想扩展世界，又倾向先观察关系、自己处理问题。探索与谨慎能很好合作；也可能每次都把计划做完了，却没有任何人知道你去了哪里。小提醒：给可信的人留一个轻松的联络，不用独自消失。\n\n猫咪营业范围：地图很大，朋友圈很小。\n\n晒图句：**“我去看看，等熟悉了再带你。”**"},{"id":"C6","code":"+-+","name":"跨小区跑腿猫","job":"街巷协作联络员","daily_scene":"今天在这个门口蹭到一条近路，明天在另一个院子找到水碗。你很懂合作，但肚皮不算合作范围。","signature":"会找支持，信任慢慢长","quote":"“一起办事可以，交心慢慢来。”","gentle_reminder":"挑一个可信的人，聊一件不用解决的闲事。","variants":{"low":{"id":"C6-low","name":"温和协商的跑腿猫","scene":"需要帮助会开口，不想答应的事也能缓缓说明，互助不用强绑。"},"mid":{"id":"C6-mid","name":"合作与距离自选猫","scene":"事情一起办，关系看场合调整，你能给合作留位置也给自己留余地。"},"high":{"id":"C6-high","name":"跨小区协作条款猫","scene":"‘这件我能做，那件做不了。’合作越多，清楚说范围越能省力。"}},"core_text":"猫咪片段：你走过不止一个小区，每处都有一两位能合作的熟人。和人保持一点距离，却知道什么时候找门卫、什么时候借条近路。\n\n人间线索：你爱走新路线，对关系谨慎，但不会把所有需要都扛在自己身上。你擅长建立实用可靠的协作；有时联系很多，真正放松的关系却少。小提醒：选一个可靠的人，聊一次和办事无关的闲话。\n\n猫咪营业范围：路很熟，交心另约。\n\n晒图句：**“不用一下熟起来，我们可以先一起走一段。”**"},{"id":"C7","code":"++-","name":"校园漫游猫","job":"图书馆门口非正式旁听生","daily_scene":"在操场晒完太阳，又去台阶旁坐一会儿。新朋友可以靠近，晚点去哪儿你自己安排。","signature":"亲近可以，行程独立","quote":"“可以一起晒太阳，也可以各走各的。”","gentle_reminder":"偶尔明确说需要陪伴，不必总显得什么都能自己搞定。","variants":{"low":{"id":"C7-low","name":"轻声说再见的校园猫","scene":"你容易亲近，也珍惜独自行程；离开可以温和说明，不必悄悄硬撑。"},"mid":{"id":"C7-mid","name":"陪伴与独行切换猫","scene":"一起晒太阳后也能各走各的，你会看场合说出自己的安排。"},"high":{"id":"C7-high","name":"行程自主的校园猫","scene":"愿意交朋友，也会直接说接下来想自己走走，亲近不用附送控制权。"}},"core_text":"猫咪片段：今天看操场，明天看图书馆。有人坐在台阶上，你可以陪一会儿；等人离开，你也会自己找下一处喜欢的地方。\n\n人间线索：你乐于去新地方、接受新善意，又能自己安排需要。你可以亲近而不时时依赖；也可能别人以为你总能搞定，忽略你偶尔想被支持。小提醒：主动说一次“这件事想请你陪我一下”。\n\n猫咪营业范围：随处可交朋友，自有落脚安排。\n\n晒图句：**“可以一起晒太阳，也可以各走各的路。”**"},{"id":"C8","code":"+++","name":"夜市社交猫","job":"流动夜班气氛组","daily_scene":"摊位一亮灯，你就有了今晚的行程。叫一声有人应，走两步又有熟人，回窝时间一拖再拖。","signature":"接近快，互助熟，容易忘记下班","quote":"“先聊两句，没准以后就是熟人。”","gentle_reminder":"给自己设个收摊时间，热闹也需要休息。","variants":{"low":{"id":"C8-low","name":"软爪夜市气氛猫","scene":"你很好聊，不舒服时也更常留缓冲；别把想休息的话藏成玩笑。"},"mid":{"id":"C8-mid","name":"热闹与分寸都有的夜市猫","scene":"该接话时接话，该收摊时收摊，表达方式随场合调整。"},"high":{"id":"C8-high","name":"会说到此下班的社交猫","scene":"你会招呼人，也会清楚表达今天先聊到这里，社交热情有自己的开关。"}},"core_text":"猫咪片段：哪家摊位亮起灯，你就去看看；几个熟面孔一招呼，你马上有了今晚的行程。需要帮忙也会开口，回窝的时间倒总是晚一点。\n\n人间线索：探索、关系与互助都能给你能量。你容易把新地方变成有人来往的地方；有时活动过多，忘了自己已经累了。小提醒：给手机和自己一起设个“今晚收摊”的时间。\n\n猫咪营业范围：社交开机快，记得充电。\n\n晒图句：**“先聊两句，没准以后就是熟人了。”**"}],"suffixes":{"low":"软爪缓冲版**：“你更常先留一点余地，再温和说出边界。这个方式有缓冲感；如果绕得太远，对方可能没听懂。猫咪提醒：轻声说，也可以说得清楚。”","mid":"看场合伸爪版**：“你会看关系和情境决定表达方式，有时委婉，有时直说。猫咪提醒：选哪种方式都可以，别把真正的需要省略掉。”","high":"边界当场说明版**：“你更愿意及时把不舒服和需求讲清。直接不等于攻击，也不必加大音量。猫咪提醒：说明‘我希望怎么做’，比给别人贴标签更有用。”"}},"end":{"name":"末世来临，你会变成什么动物？","equal_title":"你有不止一套末世应对方案","intro":"这是虚构城市故事中的应对风格，看看你的队伍位置。","bases":[{"id":"E1","code":"---","name":"带壳守城的陆龟","job":"据点秩序与个人库存管理员","daily_scene":"小队还在争论名称，你已经把自己的物件摆好。谁顺手挪了一样，你第二天就能发现。","signature":"据点稳、独立负责、先规划","quote":"“先安顿好，再走下一步。”","gentle_reminder":"别等每个格子填满，才愿意做已经明确的小事。","variants":{"low":{"id":"E1-low","name":"小圈安顿陆龟","scene":"先把自己和已承诺照顾者的安排做稳，今天的余力也可以用来恢复。"},"mid":{"id":"E1-mid","name":"范围协商陆龟","scene":"自己的据点与公共需要都看看，答应多少先说明，不把备用精力全部填满。"},"high":{"id":"E1-high","name":"社区据点维护陆龟","scene":"基本保障充足时，你愿意把细致安排也用在公共需要上，接多少任务仍有范围。"}},"core_text":"故事片段：别人急着给队伍起名字，你先把自己的角落安顿好。东西放哪儿、今天做什么，你心里有一份慢慢形成的清单。\n\n应对线索：你偏好据点、独立负责和先整理后执行。这个风格有助于保持秩序；变化多时，也可能太想等计划齐全才开始。小提醒：先确定足够清楚的第一步，允许计划有空白。\n\n队伍中的位置：稳定据点的独立维护者。需要互补：能及时帮你同步变化的伙伴。\n\n晒图句：**“壳先安稳，下一步慢慢走。”**"},{"id":"E2","code":"--+","name":"据点改造师河狸","job":"临时设施改造员","daily_scene":"桌子刚摆好，你发现光不够，又挪了一遍。你不嫌重来，只怕大家一直讨论却没有能用的版本。","signature":"据点稳、独立动手、边做边改","quote":"“先做一个能用的，再优化。”","gentle_reminder":"自己的区域可以试，共用的区域先同步。","variants":{"low":{"id":"E2-low","name":"自家角落改造河狸","scene":"先把自己与已承诺者的区域做得能用，个人恢复也是值得完成的事。"},"mid":{"id":"E2-mid","name":"边做边协商河狸","scene":"独立改造也考虑公共需要，共用部分先说清，余力分配可以商量。"},"high":{"id":"E2-high","name":"公共空间改造河狸","scene":"在有余力时多做一点公共整理，但不会默认每一次都由自己收尾。"}},"core_text":"故事片段：你守着固定落脚处，先把一块能用的空间布置出来。桌子摆完觉得不合适？再挪一下，你不介意边做边改。\n\n应对线索：你偏好据点和独立工作，愿意先推进可逆的小事。你能较快让想法落地；可能埋头改造，忘了先问共有空间中的人。小提醒：自己负责的部分大胆试，共用的部分先同步。\n\n队伍中的位置：据点里先做出可用版本的人。需要互补：帮你整理优先级的伙伴。\n\n晒图句：**“先做一个能用的，再慢慢做得更好。”**"},{"id":"E3","code":"-+-","name":"小队值班员帝企鹅","job":"小队排班兼休息保障员","daily_scene":"表格排完，你发现有人连续占了三班——原来是你自己。于是把自己的名字也写进休息栏。","signature":"固定据点、团队分工、先排安排","quote":"“班可以轮，谁都别一直撑。”","gentle_reminder":"所有人包括你，都需要真正轮到休息。","variants":{"low":{"id":"E3-low","name":"固定小队排班企鹅","scene":"优先把固定照顾者与自己的班次安排好，有稳定安排才不必一直撑。"},"mid":{"id":"E3-mid","name":"范围清楚的值班企鹅","scene":"小圈子和公共需要都可协调，先写清责任边界，再把自己也排进休息。"},"high":{"id":"E3-high","name":"社区轮班企鹅","scene":"余力较多时愿意协调更广的互助，轮班要包括所有人，也包括你。"}},"core_text":"故事片段：你喜欢和固定队友待在一个可靠落脚点。事情先说清，班次先排好；轮到谁休息，就给谁留出位置。\n\n应对线索：你偏好固定据点、团队协作和事先规划。你能让多人配合更顺畅；有时会为了等大家统一意见而拖延小决定。小提醒：先把谁负责哪一件说清，允许小事分头决定。\n\n队伍中的位置：据点内的分工协调者。需要互补：愿意在明确范围内先行动的伙伴。\n\n晒图句：**“我们先排好班，谁也不用一直撑着。”**"},{"id":"E4","code":"-++","name":"一起开工的野牛","job":"固定据点行动召集员","daily_scene":"一听‘先整理这一块’，你已经叫好两位伙伴。旁边有人举手说想休息，你给他留下一班。","signature":"固定据点、共同开工、可逆推进","quote":"“来，先把这一小块做好。”","gentle_reminder":"问清大家的精力，再把热情分给任务。","variants":{"low":{"id":"E4-low","name":"小圈一起开工野牛","scene":"先与已承诺的伙伴做好手头任务，不需要把每一处缺口都认领回来。"},"mid":{"id":"E4-mid","name":"任务范围自选野牛","scene":"愿意共同开工，也会协商今天能承担多少，热情不自动等于无限接单。"},"high":{"id":"E4-high","name":"社区开工野牛","scene":"有余力就参与公共任务，开工之前仍会问队友累不累。"}},"core_text":"故事片段：你守着小队的落脚处，一听“先整理这一块”，就招呼伙伴开始做。事情不必一次完美，大家动起来便能逐步改。\n\n应对线索：你偏好据点和共同协作，愿意通过可逆行动推进任务。你能带动开工；也可能默认大家和你同样有精力。小提醒：开工之前问一句“谁现在需要休息”。\n\n队伍中的位置：固定据点里的行动组织者。需要互补：帮小队检查负荷和安排的伙伴。\n\n晒图句：**“这件小事，我们先一起做好。”**"},{"id":"E5","code":"+--","name":"独行路线师雪豹","job":"安全节点独立路线员","daily_scene":"路线写得清楚，联络安排也留好了。你独自去完成一段任务，回到据点发现大家只想知道你吃没吃饭。","signature":"机动、独立、按计划推进","quote":"“我有自己的路线，也会留下联系。”","gentle_reminder":"别把必要同步也当成对独立的打扰。","variants":{"low":{"id":"E5-low","name":"小圈联络雪豹","scene":"优先把自己与固定照顾者的路线和联络做好，独立也保留明确约定。"},"mid":{"id":"E5-mid","name":"两边兼顾路线雪豹","scene":"个人路线与公共需要都能纳入考虑，不同任务有不同联络范围。"},"high":{"id":"E5-high","name":"公共任务路线雪豹","scene":"在保障充足时愿意承担更广的机动任务，每段完成后清楚同步。"}},"core_text":"故事片段：你在几个已确认安全的节点间移动，每次出发前会看清任务和安排。即使独自工作，也会按约定留下联络信息。\n\n应对线索：你喜欢机动、独立负责和先做计划。你能形成清楚的个人路线；有时过度依赖自己掌握的信息，不容易及时吸收团队变化。小提醒：独立工作也留一个定期同步的窗口。\n\n队伍中的位置：有安排的独立机动者。需要互补：更新快、能提醒你新变化的伙伴。\n\n晒图句：**“我有自己的路线，也会留下联系。”**"},{"id":"E6","code":"+-+","name":"机动试路员赤狐","job":"机动小任务试做员","daily_scene":"你接一个明确小任务先做，发现不顺就改。晚上一数，忙了很多件，才想起还没留下交接记录。","signature":"机动、独立、试做与调整","quote":"“先试一小步，好用再留下。”","gentle_reminder":"完成后留几句话，别人才能接上你的进度。","variants":{"low":{"id":"E6-low","name":"个人任务试做赤狐","scene":"把自己和固定照顾者的可逆小事先完成，不必为了有用持续接单。"},"mid":{"id":"E6-mid","name":"任务协商赤狐","scene":"小圈和公共事务都可以做，先定一段范围，完成后再决定下一段。"},"high":{"id":"E6-high","name":"公共互助机动赤狐","scene":"余力可用时参与更广的试做与整理，留下记录，让别人也能接手。"}},"core_text":"故事片段：你在安全节点之间灵活换位置，拿到明确的小任务就先完成一段。有用的办法留下，不合适的办法立刻换。\n\n应对线索：你偏好机动与独立，愿意用可逆尝试获取反馈。调整快、起步轻是你的优势；任务一多也容易变成今天做了很多，却难以交接。小提醒：每做完一段就留下简短记录。\n\n队伍中的位置：灵活执行小任务的机动者。需要互补：帮你收拢记录和长期安排的伙伴。\n\n晒图句：**“先试一小步，好用的办法再留下。”**"},{"id":"E7","code":"++-","name":"带队排路线的灰狼","job":"跨节点协作规划员","daily_scene":"出发前分工很清楚，会合也有安排。有人说‘就去隔壁拿张纸’，你这次忍住没有开整场协调会。","signature":"机动、团队、先协商安排","quote":"“路可以换，约好的联络别丢。”","gentle_reminder":"简单事情配简单流程，不必每次都开大会。","variants":{"low":{"id":"E7-low","name":"固定小队路线灰狼","scene":"路线与分工优先服务已承诺的队友，承诺落实比看起来覆盖很广更重要。"},"mid":{"id":"E7-mid","name":"联络范围协商灰狼","scene":"能协调小圈也能连接公共需要，先说谁负责什么，不默认扩大承诺。"},"high":{"id":"E7-high","name":"社区协作路线灰狼","scene":"余力充足时愿意参与跨节点公共协作，简单任务仍保留简单流程。"}},"core_text":"故事片段：你喜欢与队友在不同安全点之间协作。出发前讲清分工和会合安排，宁愿多花一点时间同步，也不想让人靠猜。\n\n应对线索：你偏好机动、团队和事先规划。你能让跨节点协作有条理；有时会把同步流程做得太重，影响简单事项。小提醒：为简单任务留一个简单方案。\n\n队伍中的位置：机动小队的协调规划者。需要互补：及时反馈现场实际进度的伙伴。\n\n晒图句：**“路可以换，约好的联络别丢。”**"},{"id":"E8","code":"+++","name":"穿梭报信的雨燕","job":"安全节点消息与任务连接员","daily_scene":"你把核实的信息带到，又顺手接了一件小任务。连了三个节点以后，小队给你递来一张‘到此下班’牌。","signature":"机动、团队、行动反馈快","quote":"“消息带到了，我这一班也结束了。”","gentle_reminder":"把下一件交给伙伴，让接力包括自己的休息。","variants":{"low":{"id":"E8-low","name":"小圈消息接力雨燕","scene":"先把固定照顾者需要的已核实信息带到，做完这一班可以真正休息。"},"mid":{"id":"E8-mid","name":"范围清楚消息雨燕","scene":"公共与熟人信息都可以接，答应范围先说好，别让顺手变成全部包办。"},"high":{"id":"E8-high","name":"社区消息接力雨燕","scene":"有余力时把更多节点连起来，也会把下一棒交出，让互助真正形成接力。"}},"core_text":"故事片段：你和伙伴往返于安全节点，先把一条已经核实的消息送到，再把下一件小事接上。你一动起来，几处地方就联系得更紧。\n\n应对线索：你喜欢机动、协作和边做边改。能推动信息与任务流转；也容易接下过多联络工作，把休息排到最后。小提醒：把下一班交给别人，传递任务也传递自己的限度。\n\n队伍中的位置：机动小队的信息与任务连接者。需要互补：帮你控制任务数量的伙伴。\n\n晒图句：**“把消息带到，也记得给自己留一班休息。”**"}],"suffixes":{"low":"小圈守护版**：“你的余力更常先留给自己与已承诺照顾的人。把承诺落实也是有价值的贡献；在有余力时，仍可以自由决定是否参与更大的互助。”","mid":"范围协商版**：“你会在熟悉圈子和公共需要之间分配余力。你的任务是说清范围和条件，别让默认期待把你推到没有答应的位置。”","high":"社区互助版**：“在基本保障充足时，你愿意把更多余力交给更广的互助。这个选择能连接人，也需要清楚的停止线。先说明今天能做多少，再开始帮助。”"}}},"rules":{"option_scores":{"A":-3,"B":-1,"C":1,"D":3},"axis_question_ranges":{"A":[1,6],"B":[7,12],"C":[13,18],"D":[19,24]},"base_order":["---","--+","-+-","-++","+--","+-+","++-","+++"],"near_boundary":4,"suffix_thresholds":{"low_max":-6,"high_min":6},"candidate_order":"primary first if nonzero; all other candidates by base_order; zero branches all equal by base_order","display_order":"within each axis odd ordinal ABCD, even ordinal DCBA","generation":"fixed-library-lookup-only"}};
export const questions = {"version":"1.0.0","products":{"past":[{"id":"Q01","text":"难得有一个不用赶事的周末，附近几条街都安全方便。你更想？","options":[{"key":"A","text":"照平时路线吃饭散步"},{"key":"B","text":"熟悉路线里换一家店"},{"key":"C","text":"走一条没去过的小路"},{"key":"D","text":"整个下午都留给陌生街区"}],"display_order":["A","B","C","D"]},{"id":"Q02","text":"常吃的小店和一家同价位的新店都开着，你通常？","options":[{"key":"A","text":"还是点一直吃的那份"},{"key":"B","text":"在老店换个口味"},{"key":"C","text":"试新店但点熟悉菜"},{"key":"D","text":"新店新菜一起试"}],"display_order":["D","C","B","A"]},{"id":"Q03","text":"假设几种住处同样舒适、花费一样，你更喜欢？","options":[{"key":"A","text":"长住一个地方不用折腾"},{"key":"B","text":"长住但偶尔短住别处"},{"key":"C","text":"每隔一段时间换个地方"},{"key":"D","text":"经常移动，住处跟着旅程变"}],"display_order":["A","B","C","D"]},{"id":"Q04","text":"公园新开了一条步道，老步道也很好。你会？","options":[{"key":"A","text":"继续走固定那条"},{"key":"B","text":"等别人介绍后偶尔走新路"},{"key":"C","text":"抽一次专门去走新路"},{"key":"D","text":"很快把周边没走过的路都逛一遍"}],"display_order":["D","C","B","A"]},{"id":"Q05","text":"看完一部很喜欢的作品，下一次空闲你倾向？","options":[{"key":"A","text":"重看最熟悉的部分"},{"key":"B","text":"先重看，再找类似作品"},{"key":"C","text":"同类型挑一部没看过的"},{"key":"D","text":"换个完全不同的类型"}],"display_order":["A","B","C","D"]},{"id":"Q06","text":"一天临时空出两小时，没有必须处理的事。你更愿意？","options":[{"key":"A","text":"恢复自己的固定小习惯"},{"key":"B","text":"固定安排加一点小变化"},{"key":"C","text":"临时尝试一件新事"},{"key":"D","text":"干脆不设安排，看看会遇见什么"}],"display_order":["D","C","B","A"]},{"id":"Q07","text":"一天都比较轻松，晚上终于有空，你最自然的安排是？","options":[{"key":"A","text":"自己待着就很满足"},{"key":"B","text":"自己待着，偶尔回几条消息"},{"key":"C","text":"找一位熟人一起消磨时间"},{"key":"D","text":"约几位合得来的人一起待着"}],"display_order":["A","B","C","D"]},{"id":"Q08","text":"周末去吃一家不错的小店，同伴都好约，你希望？","options":[{"key":"A","text":"自己慢慢吃"},{"key":"B","text":"自己吃，吃完再跟人聊"},{"key":"C","text":"和一位熟人一起吃"},{"key":"D","text":"和几位熟人边吃边聊"}],"display_order":["D","C","B","A"]},{"id":"Q09","text":"有件小喜事，不涉及隐私，你通常？","options":[{"key":"A","text":"留给自己回味"},{"key":"B","text":"过一阵提给一个人"},{"key":"C","text":"很快告诉亲近的人"},{"key":"D","text":"想当面和几个人一起开心"}],"display_order":["A","B","C","D"]},{"id":"Q10","text":"一场舒服的聚会结束，你往往？","options":[{"key":"A","text":"很想立刻拥有自己的安静时间"},{"key":"B","text":"回去安静一会儿，之后再联系"},{"key":"C","text":"还愿意和一个人多聊会儿"},{"key":"D","text":"意犹未尽，想继续一起活动"}],"display_order":["D","C","B","A"]},{"id":"Q11","text":"家人或朋友约你度过一个不用办事的下午，你最喜欢？","options":[{"key":"A","text":"各自有各自的时间"},{"key":"B","text":"一起吃顿饭，剩下各自安排"},{"key":"C","text":"大半天一起活动，留点独处"},{"key":"D","text":"从吃饭到散步都一起"}],"display_order":["A","B","C","D"]},{"id":"Q12","text":"出门散步，有独处和陪伴的自由，你一般选？","options":[{"key":"A","text":"基本都自己走"},{"key":"B","text":"多数自己走，偶尔结伴"},{"key":"C","text":"多数想找个熟人一起"},{"key":"D","text":"几乎每次都想有人同行"}],"display_order":["D","C","B","A"]},{"id":"Q13","text":"看到街角特别好看的光影，你首先想？","options":[{"key":"A","text":"多看一会儿就够了"},{"key":"B","text":"拍照留给自己"},{"key":"C","text":"配几句话记录下来"},{"key":"D","text":"用照片、文字或画做点完整表达"}],"display_order":["A","B","C","D"]},{"id":"Q14","text":"发现一个喜欢的手工主题，材料可以免费试用，你会？","options":[{"key":"A","text":"欣赏别人做的就很开心"},{"key":"B","text":"保存教程，暂时不动手"},{"key":"C","text":"试着做个小东西"},{"key":"D","text":"持续动手做出自己的版本"}],"display_order":["D","C","B","A"]},{"id":"Q15","text":"一段经历让你久久不能忘记，你通常如何留住？","options":[{"key":"A","text":"在心里反复回味"},{"key":"B","text":"收藏相关照片或物件"},{"key":"C","text":"写几句或讲给别人"},{"key":"D","text":"整理成一篇记录、一段视频或作品"}],"display_order":["A","B","C","D"]},{"id":"Q16","text":"好听的歌反复听了几遍，你更自然的反应？","options":[{"key":"A","text":"静静听，享受就好"},{"key":"B","text":"收藏并琢磨喜欢哪里"},{"key":"C","text":"哼唱或写几句自己的感受"},{"key":"D","text":"试唱、改词或做相关创作"}],"display_order":["D","C","B","A"]},{"id":"Q17","text":"家里一个小角落可以任你布置，也有人提供现成方案，你倾向？","options":[{"key":"A","text":"直接选舒服的现成方案"},{"key":"B","text":"现成方案里挑几样组合"},{"key":"C","text":"自己试着摆出一种效果"},{"key":"D","text":"从构想到摆放都按自己的想法来"}],"display_order":["A","B","C","D"]},{"id":"Q18","text":"有一场主题分享，听和分享都不影响评价，你更愿意？","options":[{"key":"A","text":"做听众，吸收就满足"},{"key":"B","text":"听为主，偶尔回应"},{"key":"C","text":"带一点自己的内容分享"},{"key":"D","text":"准备一份自己的表达拿出来"}],"display_order":["D","C","B","A"]},{"id":"Q19","text":"逛旧货摊，几件小物都不贵，你最会留意？","options":[{"key":"A","text":"哪个现在用得上"},{"key":"B","text":"是否耐用顺手，也看看样子"},{"key":"C","text":"它的年代和留下的痕迹"},{"key":"D","text":"它像藏着谁的一段故事"}],"display_order":["A","B","C","D"]},{"id":"Q20","text":"给熟人挑同价位的小礼物，你更看重？","options":[{"key":"A","text":"刚好满足一个实际需要"},{"key":"B","text":"好用，也有一点好看的细节"},{"key":"C","text":"能让对方想到共同经历"},{"key":"D","text":"有一个只有彼此懂的象征"}],"display_order":["D","C","B","A"]},{"id":"Q21","text":"看见老小区里还亮着的一扇窗，你更常想？","options":[{"key":"A","text":"这里的户型和居住条件"},{"key":"B","text":"里面的人正在做什么具体事"},{"key":"C","text":"这盏灯让人有种熟悉的感觉"},{"key":"D","text":"忍不住想出一段关于等待或归家的故事"}],"display_order":["A","B","C","D"]},{"id":"Q22","text":"保存一张旅行照片，你最想留下的是？","options":[{"key":"A","text":"清楚记录地点和路线"},{"key":"B","text":"当天真实发生了什么"},{"key":"C","text":"那天的心情与气氛"},{"key":"D","text":"一种难以说明但忘不掉的意味"}],"display_order":["D","C","B","A"]},{"id":"Q23","text":"朋友说“这家店很有感觉”，你理解它主要靠？","options":[{"key":"A","text":"座位、灯光、服务等具体条件"},{"key":"B","text":"具体条件加上整体舒适感"},{"key":"C","text":"整体气氛是否让人产生情绪"},{"key":"D","text":"是否让人联想到一段生活或故事"}],"display_order":["A","B","C","D"]},{"id":"Q24","text":"写一句话描述今天，你会更靠近？","options":[{"key":"A","text":"今天做了哪些事"},{"key":"B","text":"做了什么以及哪里顺利"},{"key":"C","text":"今天像什么心情"},{"key":"D","text":"用一个意象或比喻留下今天"}],"display_order":["D","C","B","A"]}],"next":[{"id":"Q01","text":"下一世的房租和生活费都解决了，你希望住处怎么安排？","options":[{"key":"A","text":"一处一直能回去的家"},{"key":"B","text":"固定住处加偶尔出游"},{"key":"C","text":"两三个地方轮换住"},{"key":"D","text":"想去哪儿就在哪儿暂住"}],"display_order":["A","B","C","D"]},{"id":"Q02","text":"孟婆给你一张通行证，不用上班也不必赶路，你最想？","options":[{"key":"A","text":"总能回到最熟悉的地方"},{"key":"B","text":"从熟悉的地方偶尔出发"},{"key":"C","text":"经常去不同地方看看"},{"key":"D","text":"不设归期地慢慢走"}],"display_order":["D","C","B","A"]},{"id":"Q03","text":"你喜欢的生活已经形成，转世办问要不要换一个地方，你会？","options":[{"key":"A","text":"更想在原处长久生活"},{"key":"B","text":"很少换，偶尔体验一下"},{"key":"C","text":"住够一段时间就换"},{"key":"D","text":"把不断移动当作生活本身"}],"display_order":["A","B","C","D"]},{"id":"Q04","text":"下一世的四季，你希望怎么度过？","options":[{"key":"A","text":"看同一个地方四季变化"},{"key":"B","text":"大部分留在原处，短暂出游"},{"key":"C","text":"每季换一个不同地方"},{"key":"D","text":"跟着喜欢的气候一直走"}],"display_order":["D","C","B","A"]},{"id":"Q05","text":"给下一世的住处选一项功能，你最看重？","options":[{"key":"A","text":"无论多久都有固定归处"},{"key":"B","text":"固定归处，也方便出门"},{"key":"C","text":"可以轻松更换居住地点"},{"key":"D","text":"所有行李都能随时带走"}],"display_order":["A","B","C","D"]},{"id":"Q06","text":"一份自由的生活邀请摆在面前，你最想要哪种日程？","options":[{"key":"A","text":"长久重复喜欢的日常"},{"key":"B","text":"固定日常中安排少量旅行"},{"key":"C","text":"日常常随所在地点调整"},{"key":"D","text":"很少固定，让路途决定日常"}],"display_order":["D","C","B","A"]},{"id":"Q07","text":"下一世不必讨好谁，你希望每天有多少共同生活？","options":[{"key":"A","text":"大部分时间只属于自己"},{"key":"B","text":"偶尔和亲近的人相聚"},{"key":"C","text":"常与亲近的人一起待着"},{"key":"D","text":"每天都有熟悉的人共同生活"}],"display_order":["A","B","C","D"]},{"id":"Q08","text":"选一个完全舒服的住所，你希望周围住着？","options":[{"key":"A","text":"邻居友善但各自独立"},{"key":"B","text":"有一两个可以偶尔来往的人"},{"key":"C","text":"几位经常串门的熟人"},{"key":"D","text":"一群能自然一起吃饭散步的人"}],"display_order":["D","C","B","A"]},{"id":"Q09","text":"下一世的晚饭已经不用操心，你想怎么吃？","options":[{"key":"A","text":"一个人自在地吃"},{"key":"B","text":"多数自己吃，偶尔约人"},{"key":"C","text":"多数和一位亲近的人吃"},{"key":"D","text":"常常有一桌合得来的人"}],"display_order":["A","B","C","D"]},{"id":"Q10","text":"宇宙给你安排一段没有任务的下午，你更想？","options":[{"key":"A","text":"不被找，自己安排"},{"key":"B","text":"自己安排，偶尔和人联系"},{"key":"C","text":"和亲近的人一起消磨"},{"key":"D","text":"从头到尾都有人一起玩"}],"display_order":["D","C","B","A"]},{"id":"Q11","text":"下一世遇见很漂亮的晚霞，你更希望？","options":[{"key":"A","text":"留下完全属于自己的片刻"},{"key":"B","text":"先独享，再发给某个人"},{"key":"C","text":"有个人一起安静看"},{"key":"D","text":"几个喜欢的人都在旁边"}],"display_order":["A","B","C","D"]},{"id":"Q12","text":"如果能自由选择人与人之间的距离，你更想？","options":[{"key":"A","text":"独立生活，联系由自己决定"},{"key":"B","text":"独立生活，有少量稳定联系"},{"key":"C","text":"独立空间和频繁陪伴兼有"},{"key":"D","text":"生活大部分都能自然共享"}],"display_order":["D","C","B","A"]},{"id":"Q13","text":"下一世不用靠成果换认可，拥有无限画纸，你最想？","options":[{"key":"A","text":"只欣赏喜欢的画就好"},{"key":"B","text":"偶尔随意涂两笔"},{"key":"C","text":"经常画些属于自己的东西"},{"key":"D","text":"想长期做出一组自己的作品"}],"display_order":["A","B","C","D"]},{"id":"Q14","text":"转世窗口给你一块不用靠它赚钱的小院，你会想？","options":[{"key":"A","text":"坐着看已有的花草"},{"key":"B","text":"偶尔打理，不设目标"},{"key":"C","text":"亲手种出一些喜欢的花"},{"key":"D","text":"从头养成一座自己的花园"}],"display_order":["D","C","B","A"]},{"id":"Q15","text":"下一世的饭菜已经有人安排，另有设备齐全的厨房，你想？","options":[{"key":"A","text":"享用现成饭菜就好"},{"key":"B","text":"偶尔随心做一道"},{"key":"C","text":"经常研究和做喜欢的菜"},{"key":"D","text":"想慢慢做出自己的拿手菜单"}],"display_order":["A","B","C","D"]},{"id":"Q16","text":"一段让你开心的经历结束，你理想中的反应是？","options":[{"key":"A","text":"开心过就够了"},{"key":"B","text":"留几张照片，不再整理"},{"key":"C","text":"做一份简单记录"},{"key":"D","text":"做成可以反复看的文字、照片集或作品"}],"display_order":["D","C","B","A"]},{"id":"Q17","text":"下一世的空间已经很舒服，但可以自由改造，你更想？","options":[{"key":"A","text":"好好享受现成布置"},{"key":"B","text":"偶尔换一点小装饰"},{"key":"C","text":"亲手改变不少细节"},{"key":"D","text":"做出一个明显属于自己的空间"}],"display_order":["A","B","C","D"]},{"id":"Q18","text":"你不用成名，做的东西也可以只留给自己，你会？","options":[{"key":"A","text":"不需要作品，体验就满足"},{"key":"B","text":"偶尔做一点小东西"},{"key":"C","text":"持续做些属于自己的成果"},{"key":"D","text":"想长久经营一种创作或栽培"}],"display_order":["D","C","B","A"]},{"id":"Q19","text":"下一世的住处，哪个环境最让你心动？","options":[{"key":"A","text":"非常安静，几乎没额外声音"},{"key":"B","text":"安静为主，偶尔有生活声"},{"key":"C","text":"白天有音乐、行人和店铺声"},{"key":"D","text":"常有丰富声音和热闹活动"}],"display_order":["A","B","C","D"]},{"id":"Q20","text":"一个没有负担的休息日，你想要多少新鲜体验？","options":[{"key":"A","text":"简单做一两件熟悉的事"},{"key":"B","text":"简单为主，加一点小惊喜"},{"key":"C","text":"多安排几种不同体验"},{"key":"D","text":"从早到晚都有新鲜东西可感受"}],"display_order":["D","C","B","A"]},{"id":"Q21","text":"转世办准备四种节日氛围，你更喜欢？","options":[{"key":"A","text":"安静度过，照常生活"},{"key":"B","text":"小小布置，轻轻庆祝"},{"key":"C","text":"有灯、有音乐、有几项活动"},{"key":"D","text":"热闹集市、表演和丰富感官体验"}],"display_order":["A","B","C","D"]},{"id":"Q22","text":"下一世挑一条可以常走的街，你更想？","options":[{"key":"A","text":"安静清爽，店少人少"},{"key":"B","text":"有几家小店，整体安静"},{"key":"C","text":"店铺丰富，有适度人流"},{"key":"D","text":"到处有摊位、灯光和活动"}],"display_order":["D","C","B","A"]},{"id":"Q23","text":"给你的理想房间选颜色和物件，你偏向？","options":[{"key":"A","text":"少量颜色，物件很少"},{"key":"B","text":"简单底色，几样小点缀"},{"key":"C","text":"多些颜色和喜欢的收藏"},{"key":"D","text":"丰富颜色、纹理和随处可看的细节"}],"display_order":["A","B","C","D"]},{"id":"Q24","text":"你理想中的日子结束时，会更喜欢哪种感觉？","options":[{"key":"A","text":"一天安静，没被太多东西打扰"},{"key":"B","text":"有几件舒服的小事"},{"key":"C","text":"感受了不少不同的东西"},{"key":"D","text":"满是画面、声音和新鲜体验"}],"display_order":["D","C","B","A"]}],"cat":[{"id":"Q01","text":"平时散步，几条路线都安全、方便，你一般？","options":[{"key":"A","text":"固定走最熟悉的一条"},{"key":"B","text":"常走固定路线，偶尔换"},{"key":"C","text":"常换路线，保留几条熟悉的"},{"key":"D","text":"喜欢不断找没走过的路线"}],"display_order":["A","B","C","D"]},{"id":"Q02","text":"空闲时在家附近活动，你通常到哪里？","options":[{"key":"A","text":"总是那几个固定地方"},{"key":"B","text":"固定地方为主，加一两个新点"},{"key":"C","text":"常去周边不同街区"},{"key":"D","text":"想逐渐把活动范围扩得更远"}],"display_order":["D","C","B","A"]},{"id":"Q03","text":"两处小店一样好、价格相同，一处熟悉一处陌生，你更常？","options":[{"key":"A","text":"回熟悉的店"},{"key":"B","text":"大多数回熟悉的，偶尔试新店"},{"key":"C","text":"多数试新店，偶尔回熟悉的"},{"key":"D","text":"喜欢持续找新的小店"}],"display_order":["A","B","C","D"]},{"id":"Q04","text":"住处安稳，周末不赶时间，你更喜欢？","options":[{"key":"A","text":"在固定地盘慢慢待着"},{"key":"B","text":"原地为主，短暂出去看看"},{"key":"C","text":"用大半天探索周围"},{"key":"D","text":"出门走远一点，扩大自己的地图"}],"display_order":["D","C","B","A"]},{"id":"Q05","text":"想找一个坐着发呆的地方，你通常？","options":[{"key":"A","text":"去一直喜欢的同一个位置"},{"key":"B","text":"在几个固定位置中换"},{"key":"C","text":"常试附近不同位置"},{"key":"D","text":"喜欢寻找全新的落脚点"}],"display_order":["A","B","C","D"]},{"id":"Q06","text":"经常经过一条没进去过的安全小街，你会？","options":[{"key":"A","text":"仍按惯常路线走"},{"key":"B","text":"很偶尔绕进去一次"},{"key":"C","text":"有空就进去看看"},{"key":"D","text":"会继续探索它连接的其他街巷"}],"display_order":["D","C","B","A"]},{"id":"Q07","text":"朋友介绍了一个礼貌、没有明显风险的新朋友，你会？","options":[{"key":"A","text":"先保持距离，观察多次"},{"key":"B","text":"简单交流，熟悉后再靠近"},{"key":"C","text":"愿意先聊一些个人兴趣"},{"key":"D","text":"很快愿意把对方纳入日常来往"}],"display_order":["A","B","C","D"]},{"id":"Q08","text":"新认识的人答应了一件小事，尚无履约记录，你通常？","options":[{"key":"A","text":"暂不期待，先看几次行动"},{"key":"B","text":"留有余地，等第一次兑现"},{"key":"C","text":"愿意先相信这次会做到"},{"key":"D","text":"初期就容易形成积极信任"}],"display_order":["D","C","B","A"]},{"id":"Q09","text":"一位普通新邻居向你表达友好，后续也礼貌，你一般？","options":[{"key":"A","text":"多次见面后才放松"},{"key":"B","text":"先点头来往，慢慢熟悉"},{"key":"C","text":"几次交流后就愿意多聊"},{"key":"D","text":"很快愿意建立轻松邻里联系"}],"display_order":["A","B","C","D"]},{"id":"Q10","text":"加入一个有熟人介绍、规则清楚的新兴趣小组，你会？","options":[{"key":"A","text":"观察较长时间再参与交流"},{"key":"B","text":"先少量参与，逐步融入"},{"key":"C","text":"较快和成员聊起共同兴趣"},{"key":"D","text":"初期就自然地投入交流"}],"display_order":["D","C","B","A"]},{"id":"Q11","text":"一个新朋友记得你的饮食偏好，做了小小照顾，你更常？","options":[{"key":"A","text":"当作一次善意，仍需长期观察"},{"key":"B","text":"有好感，继续慢慢了解"},{"key":"C","text":"更愿意与对方建立联系"},{"key":"D","text":"很快产生亲近感并增加来往"}],"display_order":["A","B","C","D"]},{"id":"Q12","text":"回想自己认识靠谱新朋友的过程，你通常需要？","options":[{"key":"A","text":"很长时间和多次验证"},{"key":"B","text":"一段时间与几次稳定来往"},{"key":"C","text":"不多的几次良好交流"},{"key":"D","text":"初次相处良好就比较容易放松"}],"display_order":["D","C","B","A"]},{"id":"Q13","text":"手头一个小任务卡住了，有可信的人愿意帮，也不会欠人情，你会？","options":[{"key":"A","text":"尽量自己完成全程"},{"key":"B","text":"自己试很久再问一点"},{"key":"C","text":"自己试一下就请教"},{"key":"D","text":"很早就约对方一起处理"}],"display_order":["A","B","C","D"]},{"id":"Q14","text":"熟人明确说“需要帮忙随时说”，遇到搬一点东西这样的小事，你一般？","options":[{"key":"A","text":"能自己做就不联系"},{"key":"B","text":"实在不方便才联系"},{"key":"C","text":"有合适帮手就开口"},{"key":"D","text":"主动商量一起分工完成"}],"display_order":["D","C","B","A"]},{"id":"Q15","text":"最近有点烦，可信的朋友有时间听，事情不涉及隐私，你通常？","options":[{"key":"A","text":"主要自己消化"},{"key":"B","text":"自己消化很久，最后提一点"},{"key":"C","text":"会主动找人聊一会儿"},{"key":"D","text":"很自然地表达需要并约人陪伴"}],"display_order":["A","B","C","D"]},{"id":"Q16","text":"一个共同活动的准备，你手里的任务不难，但可以找人协作，你倾向？","options":[{"key":"A","text":"独自完成自己的部分"},{"key":"B","text":"大部分自己做，只求少量协助"},{"key":"C","text":"和一个人分着做"},{"key":"D","text":"主动把需要说清，一起组织分工"}],"display_order":["D","C","B","A"]},{"id":"Q17","text":"手机一项设置不会用，可信的人愿意教，也有教程，你通常？","options":[{"key":"A","text":"从头自己看教程解决"},{"key":"B","text":"先查很久，再问一点"},{"key":"C","text":"查一下，不懂就问"},{"key":"D","text":"直接请人一起看，并说明卡在哪里"}],"display_order":["A","B","C","D"]},{"id":"Q18","text":"别人合理地帮了你一点小忙，后来再有类似需要，你会？","options":[{"key":"A","text":"仍优先全程自己处理"},{"key":"B","text":"比以前稍愿意开口"},{"key":"C","text":"能主动寻求相似帮助"},{"key":"D","text":"会形成自然的互助来往"}],"display_order":["D","C","B","A"]},{"id":"Q19","text":"室友把公共区域弄乱，沟通安全、关系正常，你一般如何提出？","options":[{"key":"A","text":"等平静下来再柔和提起"},{"key":"B","text":"找个合适时机委婉说明"},{"key":"C","text":"较快清楚说出希望怎么整理"},{"key":"D","text":"当场明确说明需求并商量规则"}],"display_order":["A","B","C","D"]},{"id":"Q20","text":"家庭群有人连续问你不想回答的私事，你会？","options":[{"key":"A","text":"先换话题，晚些私下说明"},{"key":"B","text":"用轻松说法表达不想聊"},{"key":"C","text":"直接说这部分暂时不讨论"},{"key":"D","text":"当场清楚说明边界和希望"}],"display_order":["D","C","B","A"]},{"id":"Q21","text":"熟人临时加一件你无法承担的事，你通常？","options":[{"key":"A","text":"先缓一下，再找温和说法拒绝"},{"key":"B","text":"委婉说明自己不方便"},{"key":"C","text":"直接说这次做不了"},{"key":"D","text":"立即明确拒绝，并说明以后怎么约"}],"display_order":["A","B","C","D"]},{"id":"Q22","text":"一句玩笑让你不舒服，对方也愿意沟通，你会？","options":[{"key":"A","text":"先消化，之后柔和提起"},{"key":"B","text":"用轻松方式说不喜欢"},{"key":"C","text":"较快直接说明不舒服"},{"key":"D","text":"当场清楚说以后请别这样开玩笑"}],"display_order":["D","C","B","A"]},{"id":"Q23","text":"熟人借东西超过约定时间，你希望拿回来，会？","options":[{"key":"A","text":"过一阵柔和问起"},{"key":"B","text":"委婉提醒原先约定"},{"key":"C","text":"直接提出归还时间"},{"key":"D","text":"当场明确新的归还安排"}],"display_order":["A","B","C","D"]},{"id":"Q24","text":"同行的人改变计划，但你想保留自己的安排，你会？","options":[{"key":"A","text":"晚些温和说明分开行动"},{"key":"B","text":"找个缓冲说法表达不同安排"},{"key":"C","text":"直接说我想按原计划"},{"key":"D","text":"立即清楚说明自己的选择并协调会合"}],"display_order":["D","C","B","A"]}],"end":[{"id":"Q01","text":"两个集合点均已确认安全，物资一样充足，路线也通畅。你倾向？","options":[{"key":"A","text":"长久留在一个点安排生活"},{"key":"B","text":"以一个点为主，少量往返"},{"key":"C","text":"经常在两点间活动"},{"key":"D","text":"喜欢随任务在不同安全点间机动"}],"display_order":["A","B","C","D"]},{"id":"Q02","text":"除必要行动外，你有自由时间，周围区域已确认安全，你更愿意？","options":[{"key":"A","text":"留在据点维护自己的角落"},{"key":"B","text":"据点为主，偶尔去附近看看"},{"key":"C","text":"多去附近不同点了解情况"},{"key":"D","text":"扩展自己的安全节点地图"}],"display_order":["D","C","B","A"]},{"id":"Q03","text":"如果可选长期岗位，保障与工作量相同，你喜欢？","options":[{"key":"A","text":"固定地点的维护岗位"},{"key":"B","text":"固定岗位加少量外出"},{"key":"C","text":"常在几个安全点之间轮换"},{"key":"D","text":"在已确认安全的节点间流动工作"}],"display_order":["A","B","C","D"]},{"id":"Q04","text":"几个安全节点的信息会及时同步，不需要冒险搜寻，你想？","options":[{"key":"A","text":"信息送来，自己守住一处"},{"key":"B","text":"偶尔亲自往返确认"},{"key":"C","text":"经常亲自到不同点看看"},{"key":"D","text":"把安全往返和节点连接当作主要角色"}],"display_order":["D","C","B","A"]},{"id":"Q05","text":"新的安全休息点开放，原点也保持同样保障，你会？","options":[{"key":"A","text":"继续在原点休息"},{"key":"B","text":"先保留原点，偶尔去新点"},{"key":"C","text":"想轮换着使用两个点"},{"key":"D","text":"更喜欢按当天位置灵活选点"}],"display_order":["A","B","C","D"]},{"id":"Q06","text":"故事恢复期可以选择同等条件的生活方式，你倾向？","options":[{"key":"A","text":"建好一个长期据点"},{"key":"B","text":"固定据点加少量移动"},{"key":"C","text":"多个据点轮换生活"},{"key":"D","text":"持续在安全节点间移动"}],"display_order":["D","C","B","A"]},{"id":"Q07","text":"一项不涉及危险的整理任务，独立或协作都能完成，你更愿意？","options":[{"key":"A","text":"独立完成，结束时同步"},{"key":"B","text":"独立为主，偶尔交流"},{"key":"C","text":"两三人分工并经常沟通"},{"key":"D","text":"与小队紧密分工、共同推进"}],"display_order":["A","B","C","D"]},{"id":"Q08","text":"清点公共用品，四种安排工作量相同，你选？","options":[{"key":"A","text":"负责一块独立区域"},{"key":"B","text":"自己清点，偶尔核对"},{"key":"C","text":"两人互相配合清点"},{"key":"D","text":"小队共同分工、实时协调"}],"display_order":["D","C","B","A"]},{"id":"Q09","text":"安全点安排生活信息板，你最自然的角色是？","options":[{"key":"A","text":"独立做好负责的一栏"},{"key":"B","text":"独立写，完成后与人核对"},{"key":"C","text":"和一位伙伴共同整理"},{"key":"D","text":"组织几个人一起协调信息"}],"display_order":["A","B","C","D"]},{"id":"Q10","text":"每天可以安排一个同等长的休息时段，你喜欢？","options":[{"key":"A","text":"自己休息，保留必要联络"},{"key":"B","text":"大部分自己，短暂和人交流"},{"key":"C","text":"与少量伙伴共同休息"},{"key":"D","text":"跟小队一起吃饭聊天、同步情况"}],"display_order":["D","C","B","A"]},{"id":"Q11","text":"同一任务可以独自完成，也可与靠谱队友完成，你通常？","options":[{"key":"A","text":"更愿意自己负责全程"},{"key":"B","text":"自己做，少量借助队友"},{"key":"C","text":"愿意明确分工、共同完成"},{"key":"D","text":"更喜欢持续配合、相互补位"}],"display_order":["A","B","C","D"]},{"id":"Q12","text":"制定明天的安全日程，你倾向？","options":[{"key":"A","text":"先独立安排自己部分再同步"},{"key":"B","text":"自己安排为主，留联络窗口"},{"key":"C","text":"和伙伴共同商量安排"},{"key":"D","text":"与小队一起形成共同日程"}],"display_order":["D","C","B","A"]},{"id":"Q13","text":"已确认安全，用品也齐备，现在要布置休息角落，你先？","options":[{"key":"A","text":"列好完整安排再开始"},{"key":"B","text":"整理主要步骤后开始"},{"key":"C","text":"定第一步，做着再调整"},{"key":"D","text":"先完成一个可逆小步骤，再逐步整理"}],"display_order":["A","B","C","D"]},{"id":"Q14","text":"新收到一批可使用的普通用品，安全检查已完成，你通常？","options":[{"key":"A","text":"先做完整分类和使用计划"},{"key":"B","text":"先分主要类别，再使用"},{"key":"C","text":"先用上最明确的一部分再整理"},{"key":"D","text":"先开展可逆试用，边用边形成安排"}],"display_order":["D","C","B","A"]},{"id":"Q15","text":"明天有几项安全、轻量的事务，没有哪件特别紧急，你会？","options":[{"key":"A","text":"今天先排好完整顺序"},{"key":"B","text":"排出重点和大致顺序"},{"key":"C","text":"先选第一件，后续动态安排"},{"key":"D","text":"明天先做一件，随进展调整"}],"display_order":["A","B","C","D"]},{"id":"Q16","text":"一个普通整理方案暂时没有唯一最优解，调整不会有损失，你倾向？","options":[{"key":"A","text":"比较几种方案后再落实"},{"key":"B","text":"看清主要差异再开始"},{"key":"C","text":"选一个可行方案先做一点"},{"key":"D","text":"直接试一个可逆版本，从反馈改"}],"display_order":["D","C","B","A"]},{"id":"Q17","text":"信息板需要更新，事实已经核实，版式随时能改，你先？","options":[{"key":"A","text":"完整设计后一次做好"},{"key":"B","text":"搭好主要框架再填写"},{"key":"C","text":"先写最重要内容再补版式"},{"key":"D","text":"先做最简可用版本，再逐步改"}],"display_order":["A","B","C","D"]},{"id":"Q18","text":"一天结束，安排仍有可调整空间，你更自然的做法？","options":[{"key":"A","text":"先复盘完整情况，再定下一步"},{"key":"B","text":"整理重点后再推进"},{"key":"C","text":"看眼前需要，先做一小步"},{"key":"D","text":"从下一件可逆小事开始，边做边复盘"}],"display_order":["D","C","B","A"]},{"id":"Q19","text":"自己和已承诺照顾的人都有保障，还有可自由安排的半小时，你通常？","options":[{"key":"A","text":"先用于本人的恢复或熟人安排"},{"key":"B","text":"主要给熟人，偶尔回应公共需要"},{"key":"C","text":"把一部分留给不熟悉的人"},{"key":"D","text":"愿意把大部分余力给公共互助"}],"display_order":["A","B","C","D"]},{"id":"Q20","text":"有额外普通用品可自由分配，基本储备已足够，你倾向？","options":[{"key":"A","text":"先留给自己与固定照顾者的后续需求"},{"key":"B","text":"熟人优先，剩余少量共享"},{"key":"C","text":"留部分备用，也主动共享一部分"},{"key":"D","text":"更愿把多数额外用品交公共互助点"}],"display_order":["D","C","B","A"]},{"id":"Q21","text":"不同联络安排同样安全、耗时相同，你优先？","options":[{"key":"A","text":"更新自己和固定照顾者的信息"},{"key":"B","text":"熟人更新为主，少量公共更新"},{"key":"C","text":"兼顾熟人和不熟悉者的联络"},{"key":"D","text":"更愿意负责公共联络与信息传递"}],"display_order":["A","B","C","D"]},{"id":"Q22","text":"不会影响自己的基本休息，可以选择不同整理对象，你更愿意？","options":[{"key":"A","text":"自己与固定照顾者的区域"},{"key":"B","text":"熟人区域为主，偶尔帮公共区域"},{"key":"C","text":"两者大致兼顾"},{"key":"D","text":"把更多空闲用于公共区域"}],"display_order":["D","C","B","A"]},{"id":"Q23","text":"已完成承诺，仍有精力回应非紧急的小请求，你一般？","options":[{"key":"A","text":"更常留给自己和熟人"},{"key":"B","text":"熟人优先，偶尔接陌生请求"},{"key":"C","text":"也会主动回应不熟悉的人"},{"key":"D","text":"愿意形成面向更多人的互助安排"}],"display_order":["A","B","C","D"]},{"id":"Q24","text":"故事恢复期有同等轻量、都值得做的事情，你更想先？","options":[{"key":"A","text":"恢复自己与固定照顾者的日常"},{"key":"B","text":"熟悉圈子为主，兼顾少量公共事务"},{"key":"C","text":"同时参与小圈子和公共恢复"},{"key":"D","text":"更多投入面向街坊社区的恢复"}],"display_order":["D","C","B","A"]}]}};
